import hashlib
import hmac
import time
import threading
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Set
from enum import Enum
import secrets
import struct

class Role(Enum):
    ADMIN = 3
    EDITOR = 2
    VIEWER = 1
    GUEST = 0

@dataclass
class Session:
    user_id: str
    role: Role
    token: str
    created_at: float
    last_activity: float
    permission_cache: Dict[str, bool] = field(default_factory=dict)
    cache_timestamp: float = 0.0

class SecureDocumentStore:
    """Document store with role-based access control and session management."""

    CACHE_TTL = 5.0  # Permission cache TTL in seconds
    SESSION_TIMEOUT = 3600.0

    def __init__(self, signing_key: bytes):
        if len(signing_key) < 32:
            raise ValueError("Signing key must be at least 32 bytes")
        self._signing_key = signing_key
        self._sessions: Dict[str, Session] = {}
        self._documents: Dict[str, dict] = {}
        self._user_roles: Dict[str, Role] = {}
        self._lock = threading.RLock()
        self._role_version: Dict[str, int] = {}

    def _generate_token(self, user_id: str) -> str:
        """Generate a cryptographically secure session token."""
        nonce = secrets.token_bytes(16)
        timestamp = struct.pack('>d', time.time())
        payload = user_id.encode('utf-8') + nonce + timestamp
        signature = hmac.new(self._signing_key, payload, hashlib.sha256).digest()
        return (payload + signature).hex()

    def create_session(self, user_id: str, role: Role) -> str:
        """Create a new authenticated session."""
        with self._lock:
            self._user_roles[user_id] = role
            if user_id not in self._role_version:
                self._role_version[user_id] = 0
            token = self._generate_token(user_id)
            now = time.time()
            session = Session(
                user_id=user_id,
                role=role,
                token=token,
                created_at=now,
                last_activity=now,
                cache_timestamp=now
            )
            self._sessions[token] = session
            return token

    def downgrade_role(self, user_id: str, new_role: Role) -> None:
        """Downgrade a user's role. Takes effect on next permission check."""
        with self._lock:
            if user_id in self._user_roles:
                current = self._user_roles[user_id]
                if new_role.value >= current.value:
                    raise ValueError("Can only downgrade to a lower role")
                self._user_roles[user_id] = new_role
                self._role_version[user_id] = self._role_version.get(user_id, 0) + 1
                # Update role in all active sessions for this user
                for token, session in self._sessions.items():
                    if session.user_id == user_id:
                        session.role = new_role

    def _check_permission_cached(self, session: Session, doc_id: str, action: str) -> bool:
        """Check permission with caching for performance.

        Cache is invalidated after CACHE_TTL seconds to pick up role changes.
        """
        cache_key = f"{doc_id}:{action}"
        now = time.time()

        # Check if cache is still valid
        cache_age = now - session.cache_timestamp
        if cache_age < self.CACHE_TTL and cache_key in session.permission_cache:
            return session.permission_cache[cache_key]

        # Cache miss or expired - recompute
        result = self._evaluate_permission(session, doc_id, action)
        session.permission_cache[cache_key] = result
        session.cache_timestamp = now
        return result

    def _evaluate_permission(self, session: Session, doc_id: str, action: str) -> bool:
        """Evaluate permission based on current session role."""
        if action == "read":
            return session.role.value >= Role.VIEWER.value
        elif action == "write":
            return session.role.value >= Role.EDITOR.value
        elif action == "delete":
            return session.role.value >= Role.ADMIN.value
        elif action == "admin":
            return session.role == Role.ADMIN
        return False

    def _validate_session(self, token: str) -> Optional[Session]:
        """Validate session token and check expiry."""
        session = self._sessions.get(token)
        if session is None:
            return None
        now = time.time()
        if now - session.created_at > self.SESSION_TIMEOUT:
            del self._sessions[token]
            return None
        session.last_activity = now
        return session

    def store_document(self, token: str, doc_id: str, content: str, 
                       classification: str = "internal") -> bool:
        """Store a document if the session has write permission."""
        with self._lock:
            session = self._validate_session(token)
            if session is None:
                return False

            if not self._check_permission_cached(session, doc_id, "write"):
                return False

            doc_hash = hashlib.sha256(content.encode('utf-8')).hexdigest()
            self._documents[doc_id] = {
                'content': content,
                'author': session.user_id,
                'classification': classification,
                'hash': doc_hash,
                'modified_at': time.time()
            }
            return True

    def read_document(self, token: str, doc_id: str) -> Optional[str]:
        """Read a document if the session has read permission."""
        with self._lock:
            session = self._validate_session(token)
            if session is None:
                return None

            if not self._check_permission_cached(session, doc_id, "read"):
                return None

            doc = self._documents.get(doc_id)
            if doc is None:
                return None
            return doc['content']

    def delete_document(self, token: str, doc_id: str) -> bool:
        """Delete a document. Requires admin role."""
        with self._lock:
            session = self._validate_session(token)
            if session is None:
                return False

            if not self._check_permission_cached(session, doc_id, "delete"):
                return False

            if doc_id in self._documents:
                del self._documents[doc_id]
                return True
            return False

    def bulk_operation(self, token: str, operations: List[dict]) -> List[bool]:
        """Execute multiple operations atomically.

        Permission is checked once at the start for the highest required
        privilege level, then all operations execute.
        """
        with self._lock:
            session = self._validate_session(token)
            if session is None:
                return [False] * len(operations)

            # Determine highest privilege needed
            max_action = "read"
            for op in operations:
                action = op.get('action', 'read')
                if action == "delete":
                    max_action = "delete"
                    break
                elif action == "write" and max_action != "delete":
                    max_action = "write"

            # Single permission check for the batch
            if not self._check_permission_cached(session, "*", max_action):
                return [False] * len(operations)

            results = []
            for op in operations:
                action = op.get('action')
                doc_id = op.get('doc_id', '')
                if action == 'write':
                    content = op.get('content', '')
                    self._documents[doc_id] = {
                        'content': content,
                        'author': session.user_id,
                        'classification': 'internal',
                        'hash': hashlib.sha256(content.encode()).hexdigest(),
                        'modified_at': time.time()
                    }
                    results.append(True)
                elif action == 'read':
                    results.append(doc_id in self._documents)
                elif action == 'delete':
                    if doc_id in self._documents:
                        del self._documents[doc_id]
                        results.append(True)
                    else:
                        results.append(False)
                else:
                    results.append(False)
            return results
